CO = ['masterovit.ru', 'prof-zabory.ru', 'zaborkin.ru', 'zavodzaborov.ru', 'raduga-zaborov.ru',
      'zaborovo.ru', 'oblzabor.ru', 'dostup-zabor.ru', 'zaboroff.ru', 'pskzabor.ru']
SC = {r['id']: r for r in csv.DictReader(open(f'{B}/data/criteria_scores.csv', encoding='utf-8')) if r['id'].startswith('C')}
def same(cid, thr):
    lst = [c for c in CO if int(SC[cid][c]) >= thr]
    return len(lst), ', '.join(lst) if lst else 'никто'
def S(cid, thr, note=''):
    n, lst = same(cid, thr); return n, f'{lst} ({cid} ≥ {thr}){"; " + note if note else ""}'

